import { readFile, mkdir, writeFile } from "node:fs/promises";
import { join as join2 } from "node:path";
import os5 from "node:os";
var DAILY_BUDGET_TOKENS = 128000;
var OPUS_DAILY_LIMIT = 20;
var DEVICE_ID_PATH = join2(os5.homedir(), ".config", "supercode", "device-id");
var OPUS_USAGE_PATH = join2(os5.homedir(), ".config", "supercode", "opus-usage.json");
var PROXY_USAGE_PATH = join2(os5.homedir(), ".config", "supercode", "proxy-usage.json");
function todayString() {
  const now4 = new Date;
  return `${now4.getUTCFullYear()}-${String(now4.getUTCMonth() + 1).padStart(2, "0")}-${String(now4.getUTCDate()).padStart(2, "0")}`;
}
function todayStart() {
  const now4 = new Date;
  return new Date(Date.UTC(now4.getUTCFullYear(), now4.getUTCMonth(), now4.getUTCDate()));
}
async function getDailyTokenUsage(userId) {
  let dbUsage = 0;
  try {
    const where = { createdAt: { gte: todayStart() } };
    if (userId)
      where.userId = userId;
    const result = await prisma_default.usageEvent.aggregate({
      _sum: { totalTokens: true },
      where
    });
    dbUsage = result._sum.totalTokens ?? 0;
  } catch {}
  const proxyUsage = userId ? await getProxyUsageForUser(userId) : 0;
  return dbUsage + proxyUsage;
}
async function getUserDailyUsage(userId) {
  const used = await getDailyTokenUsage(userId);
  const resetAt = new Date(todayStart().getTime() + 86400000).toISOString();
  return {
    used,
    limit: DAILY_BUDGET_TOKENS,
    remaining: Math.max(0, DAILY_BUDGET_TOKENS - used),
    resetAt
  };
}
async function getDailyOpusCount() {
  try {
    const data = JSON.parse(await readFile(OPUS_USAGE_PATH, "utf-8"));
    return data.date === todayString() ? data.count ?? 0 : 0;
  } catch {
    return 0;
  }
}
async function incrementDailyOpusCount() {
  const count = await getDailyOpusCount();
  await mkdir(join2(os5.homedir(), ".config", "supercode"), { recursive: true });
  await writeFile(OPUS_USAGE_PATH, JSON.stringify({ date: todayString(), count: count + 1 }));
}
async function checkDailyOpusLimit() {
  const count = await getDailyOpusCount();
  if (count >= OPUS_DAILY_LIMIT) {
    throw new Error(`Opus 4.8 daily limit reached (${count}/${OPUS_DAILY_LIMIT}). Resets at midnight UTC.`);
  }
}
async function appendProxyUsage(event) {
  try {
    let events = [];
    try {
      events = JSON.parse(await readFile(PROXY_USAGE_PATH, "utf-8"));
    } catch {}
    events.push(event);
    const cutoff = Date.now() - 86400000 * 2;
    events = events.filter((e2) => e2.timestamp > cutoff);
    await mkdir(join2(os5.homedir(), ".config", "supercode"), { recursive: true });
    await writeFile(PROXY_USAGE_PATH, JSON.stringify(events), "utf-8");
  } catch {}
}
async function getProxyUsageForUser(userId) {
  try {
    const events = JSON.parse(await readFile(PROXY_USAGE_PATH, "utf-8"));
    const today = todayStart().getTime();
    return events.filter((e2) => e2.userId === userId && e2.timestamp >= today).reduce((sum, e2) => sum + e2.totalTokens, 0);
  } catch {
    return 0;
  }
}

