function pushSkillsSection(lines) {
  const skillsDir = path6.join(os7.homedir(), ".supercode", "skills");
  const lockPath = path6.join(os7.homedir(), ".supercode", "skills-lock.json");
  let lock = {};
  try {
    lock = JSON.parse(fs8.readFileSync(lockPath, "utf-8")).skills || {};
  } catch {
    return;
  }
  const entries = Object.entries(lock);
  if (entries.length === 0)
    return;
  lines.push("## Available Skills");
  lines.push("");
  lines.push("You have the following agent skills installed. Use the `skill` tool to manage and load them:");
  lines.push('- `skill({ action: "load", name: "<skill-name>" })` — Read a skill\'s full instructions. Call this when a task matches a skill\'s description.');
  lines.push('- `skill({ action: "list" })` — List all installed skills.');
  lines.push('- `skill({ action: "install", name: "<name>", source: "<owner/repo>" })` — Install a new skill from GitHub.');
  lines.push('- `skill({ action: "remove", name: "<name>" })` — Uninstall a skill.');
  lines.push("");
  for (const [name24, def] of entries) {
    const skillFile = path6.join(skillsDir, name24, "SKILL.md");
    let description = "";
    try {
      const content = fs8.readFileSync(skillFile, "utf-8");
      const match = content.match(/description:\s*(.+)/);
      description = match ? match[1].trim() : "";
    } catch {
      description = "(not on disk — run `supercode skill sync`)";
    }
    lines.push(`- **${name24}** — ${description || "(no description)"}`);
    if (def.source) {
      lines.push(`  Source: ${def.source}`);
    }
  }
  lines.push("");
}
function formatTreeForPrompt(nodes, indent) {
  let result = "";
  for (let i = 0;i < nodes.length; i++) {
    const node = nodes[i];
    const isLast = i === nodes.length - 1;
    const prefix = isLast ? "└── " : "├── ";
    const childIndent = isLast ? "    " : "│   ";
    result += `${indent}${prefix}${node.name}${node.type === "dir" ? "/" : ""}
`;
    if (node.children && node.children.length > 0) {
      result += formatTreeForPrompt(node.children, indent + childIndent);
    }
  }
  return result;
}

