// src/lib/workspace.ts
import { resolve as resolve2 } from "node:path";
import { access } from "node:fs/promises";

class WorkspaceError extends Error {
  constructor(message) {
    super(message);
    this.name = "WorkspaceError";
  }
}
function getRoot() {
  return process.env.SUPERCODE_WORKSPACE_ROOT || process.cwd();
}
function resolvePath(filePath) {
  const root = getRoot();
  const full = resolve2(root, filePath);
  if (!full.startsWith(root)) {
    throw new WorkspaceError(`Path "${filePath}" is outside workspace root`);
  }
  return full;
}
function assertNoBinary(content, label) {
  if (content.includes("\x00")) {
    throw new WorkspaceError(`"${label}" contains binary content`);
  }
}
async function fileExists(p2) {
  try {
    await access(p2);
    return true;
  } catch {
    return false;
  }
}

// src/tools/definitions/read-file.ts
init_tool_result();
var readFileSchema = exports_external.object({
  path: exports_external.string().describe("Relative path from workspace root (e.g. 'src/index.ts', 'package.json')"),
  maxLines: exports_external.number().optional().describe("Maximum number of lines to read (omit for full file)"),
  description: exports_external.string().optional().describe("What to look for (for display)")
});
var readFileTool = {
  description: "Read the contents of a file within the workspace. Use this to examine source code, configuration files, or any file the user asks about.",
  parameters: readFileSchema,
  execute: async ({ path: filePath, maxLines }) => serialize(async () => {
    const fullPath = resolvePath(filePath);
    const content = await readFile3(fullPath, "utf-8");
    if (maxLines !== undefined) {
      const lines = content.split(`
`);
      const sliced = lines.slice(0, maxLines);
      if (lines.length > maxLines) {
        sliced.push(`
... (${lines.length - maxLines} more lines)`);
      }
      return ok({ path: filePath, content: sliced.join(`
`), totalLines: lines.length });
    }
    return ok({ path: filePath, content, totalLines: content.split(`
`).length });
  })
};

// src/tools/definitions/search-files.ts
init_zod();
init_tool_result();
import path7 from "node:path";
var searchFilesSchema = exports_external.object({
  pattern: exports_external.string().describe("Text or regex pattern to search for"),
  include: exports_external.string().optional().describe("File glob pattern to narrow search (e.g. '*.ts', '*.{tsx,jsx}')"),
  maxResults: exports_external.number().optional().default(20).describe("Maximum number of results to return")
});
var searchFilesTool = {
  description: "Search for text patterns across workspace files. Use this to find relevant code, function definitions, imports, or any text in the codebase.",
  parameters: searchFilesSchema,
  execute: async ({ pattern, include, maxResults }) => serialize(async () => {
    const execSync = (await import("node:child_process")).execSync;
    const workspaceRoot = process.env.SUPERCODE_WORKSPACE_ROOT || process.cwd();
    let cmd = `grep -rn --binary-files=without-match`;
    const includeGlob = include ?? "";
    if (includeGlob) {
      cmd += ` --include="${includeGlob}"`;
    }
    cmd += ` -m 1 "${pattern}" "${workspaceRoot}"`;
    cmd += ` 2>/dev/null | head -${maxResults ?? 20}`;
    try {
      const output = execSync(cmd, { encoding: "utf-8", maxBuffer: 1048576, timeout: 15000 });
      if (!output.trim())
        return ok({ matches: [], total: 0, pattern });
      const lines = output.trim().split(`
`).slice(0, maxResults ?? 20);
      const matches = lines.map((line) => {
        const parts = line.split(":", 2);
        const filePath = parts[0];
        if (parts.length === 2) {
          const relPath = path7.relative(workspaceRoot, filePath);
          return `${relPath}:${parts[1]}`;
        }
        return line;
      });
      return ok({ matches, total: matches.length, pattern });
    } catch {
      return ok({ matches: [], total: 0, pattern });
    }
  })
};

