init_zod();
import { mkdir as mkdir2, writeFile as writeFile2 } from "node:fs/promises";
import path8 from "node:path";
init_tool_result();
var MAX_FILE_SIZE = 1e6;
var writeFileSchema = exports_external.object({
  path: exports_external.string().describe("Relative path from workspace root (e.g. 'src/App.jsx', 'package.json')"),
  content: exports_external.string().describe("Complete file content to write"),
  description: exports_external.string().optional().describe("Brief description of what this file does (for display)")
});
var writeFileTool = {
  description: `Create a new file or overwrite an existing file in the workspace. Use this to create components, add features, fix configuration, or modify existing files (read first, then overwrite with the FULL new content — this tool cannot append or patch).

` + `IMPORTANT: write_file replaces the entire file. To add a line to an existing file, read it first, then pass the complete new content.

` + "CONTENT FORMAT: the `content` parameter is a literal string. Real newlines must be actual newline characters in the JSON, NOT the two-character sequence `\\n`. If you write `hello\\nworld`, the file will contain the literal characters backslash-n, not a newline. Use real newlines in your tool-call payload.",
  parameters: writeFileSchema,
  execute: async ({ path: filePath, content }) => serialize(async () => {
    const fullPath = resolvePath(filePath);
    assertNoBinary(content, filePath);
    if (content.length > MAX_FILE_SIZE) {
      return fail(`File "${filePath}" exceeds maximum size of 1MB`);
    }
    const fileDir = path8.dirname(fullPath);
    await mkdir2(fileDir, { recursive: true });
    await writeFile2(fullPath, content, "utf-8");
    return ok({
      path: filePath,
      size: content.length,
      action: "created"
    });
  })
};

// src/tools/definitions/edit-file.ts
init_zod();
import { readFile as readFile4, writeFile as writeFile3 } from "node:fs/promises";
init_tool_result();
var editFileSchema = exports_external.object({
  path: exports_external.string().describe("Relative path from workspace root (e.g. 'src/App.tsx')"),
  oldText: exports_external.string().describe("Exact substring to find in the existing file. Must match exactly, including whitespace and indentation."),
  newText: exports_external.string().describe("Replacement text. Use real newline characters in the JSON payload, NOT the two-character sequence `\\n`."),
  replaceAll: exports_external.boolean().optional().default(false).describe("Replace ALL occurrences of oldText (default: false — fails if more than one match)"),
  description: exports_external.string().optional().describe("Brief description of what this edit does (for display)")
});
var editFileTool = {
  description: `Make a targeted edit to an existing file by replacing a specific substring with new text. Use this when you want to add a function, change a few lines, or fix a small section WITHOUT rewriting the whole file.

` + `WORKFLOW:
` + `  1. read_file the target first so you have the exact current text.
` + "  2. Pass the EXACT `oldText` (including leading indentation and trailing newline). Copy-paste from the read output — do NOT retype.\n" + "  3. Pass `newText` with the replacement. Use real newline characters in the JSON payload, NOT literal `\\n`.\n\n" + "If `oldText` appears multiple times and `replaceAll` is false, the call fails. Set `replaceAll: true` to replace all occurrences. " + "If `oldText` appears zero times, the call fails — re-read the file and try again.\n\n" + "For creating new files, use write_file. For wholesale rewrites, use write_file after read_file.",
  parameters: editFileSchema,
  execute: async ({ path: filePath, oldText, newText, replaceAll }) => serialize(async () => {
    const fullPath = resolvePath(filePath);
    assertNoBinary(newText, filePath);
    let original;
    try {
      original = await readFile4(fullPath, "utf-8");
    } catch (err) {
      if (err?.code === "ENOENT") {
        return fail(`File "${filePath}" does not exist. Use write_file to create new files.`);
      }
      throw err;
    }
    const occurrences = original.split(oldText).length - 1;
    if (occurrences === 0) {
      return fail(`oldText not found in "${filePath}". The file may have changed since you read it. Use read_file to get the exact current content, then copy-paste the exact text (including whitespace and indentation) as oldText.`, "Read the file again and verify the exact content before retrying");
    }
    if (!replaceAll && occurrences > 1) {
      return fail(`oldText appears ${occurrences} times in "${filePath}". Use replaceAll: true to replace all, or refine oldText to match exactly one location.`, "Add more surrounding context to oldText to make it unique, or pass replaceAll: true");
    }
    const updated = original.split(oldText).join(newText);
    await writeFile3(fullPath, updated, "utf-8");
    return ok({
      path: filePath,
      replacements: occurrences,
      sizeBefore: original.length,
      sizeAfter: updated.length,
      action: "edited"
    });
  })
};

