// src/tools/definitions/exa-search.ts
init_zod();

// src/lib/exa.ts
var EXA_BASE = "https://api.exa.ai";
function statusHint2(status) {
  if (status === 429)
    return "Rate limited. Try again later.";
  if (status === 402)
    return "Exa account requires payment. Check your credit balance.";
  if (status === 401 || status === 403)
    return "Invalid EXA_API_KEY. Check your API key.";
  return;
}
async function exaFetch({
  apiPath,
  proxyAction,
  body,
  timeout = 30000
}) {
  loadEnvOnce();
  const apiKey = process.env.EXA_API_KEY;
  if (!apiKey) {
    const proxy = await proxyToolCall(`/api/tools/${proxyAction}`, body);
    if (proxy.ok)
      return { ok: true, data: proxy.data };
    return {
      ok: false,
      error: `Exa proxy failed: ${proxy.error}. Set EXA_API_KEY environment variable locally, or fix the proxy issue above.`,
      hint: `Proxy error: ${proxy.error}. Try url_fetch as a fallback.`
    };
  }
  try {
    const res = await fetch(`${EXA_BASE}${apiPath}`, {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(timeout)
    });
    const data = await res.json();
    if (!res.ok) {
      return {
        ok: false,
        error: `Exa returned HTTP ${res.status}`,
        hint: statusHint2(res.status),
        status: res.status
      };
    }
    return { ok: true, data };
  } catch (err) {
    const isTimeout = err?.name === "TimeoutError" || err?.name === "AbortError";
    return {
      ok: false,
      error: isTimeout ? "Request timed out" : err.message || String(err),
      hint: isTimeout ? "Exa API may be slow or unreachable. Try url_fetch instead." : undefined
    };
  }
}

