function renderTodoList(todos) {
  if (todos.length === 0) {
    return source_default2.hex(theme.muted)("  No todos");
  }
  const rows = [];
  let inProgressIdx = -1;
  for (let i = 0;i < todos.length; i++) {
    const t = todos[i];
    if (t.status === "in_progress")
      inProgressIdx = i;
    const statusIcon2 = t.status === "completed" ? source_default2.hex(theme.green)("✓") : t.status === "in_progress" ? source_default2.hex(theme.amber)("●") : t.status === "cancelled" ? source_default2.hex(theme.red)("✗") : source_default2.hex(theme.muted)("○");
    const prioTag = t.priority === "high" ? source_default2.hex(theme.red)(" high") : t.priority === "medium" ? source_default2.hex(theme.amber)(" med") : source_default2.hex(theme.muted)(" low");
    rows.push(`  ${statusIcon2} ${source_default2.bold(t.content)}${prioTag}`);
  }
  const completed = todos.filter((t) => t.status === "completed").length;
  const total = todos.length;
  const summary = source_default2.hex(theme.greenDim)(`  ${completed}/${total} · ${inProgressIdx >= 0 ? `active: ${todos[inProgressIdx].content}` : "none in progress"}`);
  return [...rows, "", summary].join(`
`);
}
