import fs11 from "fs/promises";
import path11 from "path";
import os9 from "os";
var SKILLS_DIR = path11.join(os9.homedir(), ".supercode", "skills");
var skillSchema = exports_external.object({
  action: exports_external.enum(["install", "remove", "list", "info", "load"]).describe("What to do with the skill"),
  name: exports_external.string().optional().describe("Skill name (required for install, remove, info, load)"),
  source: exports_external.string().optional().describe("GitHub source as owner/repo (required for install)"),
  path: exports_external.string().optional().describe("Custom path to SKILL.md within the repo (optional for install)")
});
var skillTool = {
  description: `Manage installed agent skills. Install new skills from GitHub, list installed skills, view details, or load a skill's full instructions. Install: call with action="install", name="<skill>", source="<owner/repo>". List: call with action="list". Load: call with action="load", name="<skill>" to read the full SKILL.md content.`,
  parameters: skillSchema,
  execute: async (args) => serialize(async () => {
    const { action, name: name24, source, path: skillPath } = args;
    switch (action) {
      case "install": {
        if (!name24 || !source) {
          return fail("Missing required arguments: name and source are required for install. Example: install a skill named 'frontend-design' from 'anthropics/skills'.");
        }
        await installSkill(name24, source, skillPath);
        return ok({ installed: name24, source });
      }
      case "remove": {
        if (!name24) {
          return fail("Missing required argument: name is required for remove.");
        }
        await uninstallSkill(name24);
        return ok({ removed: name24 });
      }
      case "list": {
        const skills = await listInstalledSkills();
        const list2 = skills.map((s) => ({
          name: s.name,
          description: s.description,
          source: s.definition.source
        }));
        return ok({ skills: list2, count: list2.length });
      }
      case "info": {
        if (!name24) {
          return fail("Missing required argument: name is required for info.");
        }
        const skills = await listInstalledSkills();
        const skill = skills.find((s) => s.name === name24);
        if (!skill) {
          return fail(`Skill "${name24}" not found. Use action="list" to see installed skills.`);
        }
        return ok({
          name: skill.name,
          description: skill.description,
          source: skill.definition.source,
          path: skill.definition.skillPath
        });
      }
      case "load": {
        if (!name24) {
          return fail("Missing required argument: name is required for load.");
        }
        const filePath = path11.join(SKILLS_DIR, name24, "SKILL.md");
        let content;
        try {
          content = await fs11.readFile(filePath, "utf-8");
        } catch {
          return fail(`Skill "${name24}" not found on disk. Use action="install" to install it first, then retry.`);
        }
        return ok({ name: name24, content });
      }
    }
  })
};

