// src/lib/citation-tracker.ts
class CitationTracker {
  citations = [];
  record(citation) {
    this.citations.push(citation);
  }
  recordFromToolCall(toolName, args) {
    const a = args ?? {};
    switch (toolName) {
      case "url_fetch":
      case "web_search":
        if (typeof a.url === "string") {
          this.record({ kind: "url", reference: a.url, toolName, args });
        } else if (typeof a.query === "string") {
          this.record({ kind: "search", reference: a.query, toolName, args });
        }
        break;
      case "read_file":
      case "read_instructions":
        if (typeof a.path === "string") {
          this.record({ kind: "file", reference: a.path, toolName, args });
        }
        break;
      case "search_files":
        if (typeof a.pattern === "string") {
          this.record({ kind: "search", reference: a.pattern, toolName, args });
        }
        break;
    }
  }
  all() {
    return this.citations;
  }
  urls() {
    const refs = [];
    for (const c of this.citations) {
      if (c.kind === "url")
        refs.push(c.reference);
    }
    return refs;
  }
  files() {
    const refs = [];
    for (const c of this.citations) {
      if (c.kind === "file")
        refs.push(c.reference);
    }
    return refs;
  }
  suspectClaims(response) {
    const suspects = [];
    const knownUrls = new Set(this.urls());
    const knownFiles = new Set(this.files());
    const urlRegex = /https?:\/\/[^\s)]+/g;
    let m3;
    while ((m3 = urlRegex.exec(response)) !== null) {
      const url2 = m3[0];
      if (![...knownUrls].some((u) => url2.startsWith(u) || u.startsWith(url2))) {
        suspects.push(`uncited URL: ${url2}`);
      }
    }
    const pathRegex = /(?:^|\s)((?:src|apps|packages|lib|test|tests)\/[a-zA-Z0-9_\-./]+\.[a-z]{1,5})/g;
    while ((m3 = pathRegex.exec(response)) !== null) {
      const matched = m3[1];
      if (!matched)
        continue;
      const path12 = matched;
      if (!knownFiles.has(path12) && ![...knownFiles].some((f2) => path12.startsWith(f2))) {
        const before = response.slice(Math.max(0, m3.index - 80), m3.index);
        if (!/```/.test(before.slice(before.lastIndexOf("```")))) {
          suspects.push(`uncited file path: ${path12}`);
        }
      }
    }
    return suspects;
  }
  buildCitationSentinel(response) {
    const suspects = this.suspectClaims(response);
    if (suspects.length === 0)
      return null;
    return [
      "SYSTEM NOTICE: Your previous response contains factual claims that aren't backed by any tool call this turn.",
      "",
      "Suspect claims:",
      ...suspects.map((s) => `- ${s}`),
      "",
      "For each suspect claim, either: (a) call the right tool to retrieve the actual fact, or (b) explicitly retract the claim in your next response. Do NOT continue building on uncited claims."
    ].join(`
`);
  }
  reset() {
    this.citations = [];
  }
}

