  if (info2.gitBranch) {
    lines.push(`  ${source_default2.hex(theme.greenDim)("git")}     ${source_default2.hex(theme.greenDim)("·")} ${source_default2.hex(theme.amber)(info2.gitBranch)} ${dot}`);
  }
