var currentConversationId = "";
async function handleSlashCommand(input) {
  const match = input.match(/^\/([\w-]+)\s*(.*)$/);
  if (!match)
    return null;
  const [, cmd = "", args = ""] = match;
  if (!cmd) {
    renderCommandList();
    return { type: "help" };
  }
  if (cmd.toLowerCase() === "exit") {
    return { type: "exit" };
  }
  const safeCmd = cmd.toLowerCase();
  const handler = handlers[safeCmd];
  if (!handler) {
    const { skillCommand: skillCommand2 } = await Promise.resolve().then(() => (init_skill(), exports_skill));
    const result = await skillCommand2(`load ${safeCmd}`);
    if (result?.message) {
      const userArgs = args.trim();
      if (userArgs) {
        return { type: "message", message: userArgs, skillName: result.skillName, skillContent: result.message };
      }
      return { type: "skills", message: result.message, skillName: result.skillName, trigger: true };
    }
    return { type: "unknown" };
  }
  return handler(args.trim());
}
function isSlashCommand(input) {
  return /^\//.test(input.trim());
}

