  const innerW = Math.max(40, w4 - 6);
  const pct = state.contextWindow > 0 ? Math.min(100, Math.round(state.sessionTokens / state.contextWindow * 100)) : 0;
  const available = Math.max(0, state.contextWindow - state.sessionTokens);
  const lines = [];
