  lines.push(`  ${label("Max Context")}  ${value(formatTokenCount(state.contextWindow))} ${dim4("tokens")}`);
  lines.push(`  ${label("Used")}       ${amber(formatTokenCount(state.sessionTokens))} ${dim4("tokens")}  ${amber(`(${pct}%)`)}`);
  lines.push(`  ${label("Available")}  ${value(formatTokenCount(available))} ${dim4("tokens")}  ${dim4(`(${100 - pct}%)`)}`);
  lines.push("");
