async function resolveFileReferences(input, workspaceRoot, extraPaths) {
  const content = {};
  const unresolved = [];
  const seen = new Set;
  const tryAdd = async (filePath) => {
    if (seen.has(filePath))
      return;
    seen.add(filePath);
    try {
      const resolved = workspaceRoot ? path18.resolve(workspaceRoot, filePath) : path18.resolve(filePath);
      const stat2 = await fs15.stat(resolved);
      if (stat2.isFile() && stat2.size < 512 * 1024) {
        const data = await fs15.readFile(resolved, "utf-8");
        content[resolved] = data;
      } else {
        unresolved.push(filePath);
      }
    } catch {
      unresolved.push(filePath);
    }
  };
  const refs = input.match(/@\S+/g);
  if (refs) {
    for (const ref of refs) {
      let filePath = ref.slice(1).replace(/[,.!?;:)]+$/, "");
      if (filePath.startsWith("/"))
        filePath = filePath.slice(1);
      await tryAdd(filePath);
    }
  }
  if (extraPaths) {
    for (const p2 of extraPaths) {
      await tryAdd(p2);
    }
  }
  return { content, unresolved };
}

