// src/service/chat-service.ts
class ChatService {
  async createConversation(userId, mode = "chat", title = null) {
    return prisma_default.conversation.create({
      data: {
        userId,
        mode,
        title: title || `New ${mode} conversation`
      }
    });
  }
  async getOrCreateConversation(userId, conversationId = null, mode = "chat") {
    if (conversationId) {
      const conversation = await prisma_default.conversation.findFirst({
        where: { id: conversationId, userId },
        include: {
          messages: {
            orderBy: { createdAt: "asc" }
          }
        }
      });
      if (conversation)
        return conversation;
    }
    return this.createConversation(userId, mode);
  }
  async addMessage(conversationId, role, content) {
    const contentStr = typeof content === "string" ? content : JSON.stringify(content);
    return prisma_default.message.create({
      data: { conversationId, role, content: contentStr }
    });
  }
  async getMessages(conversationId) {
    const messages = await prisma_default.message.findMany({
      where: { conversationId },
      orderBy: { createdAt: "asc" }
    });
    return messages.map((msg) => ({
      ...msg,
      content: this.parseContent(msg.content)
    }));
  }
  async getUserConversations(userId) {
    return prisma_default.conversation.findMany({
      where: { userId },
      orderBy: { updatedAt: "desc" },
      include: {
        messages: {
          take: 1,
          orderBy: { createdAt: "desc" }
        }
      }
    });
  }
  async deleteConversation(conversationId, userId) {
    return prisma_default.conversation.deleteMany({
      where: { id: conversationId, userId }
    });
  }
  async updateMode(conversationId, mode) {
    return prisma_default.conversation.update({
      where: { id: conversationId },
      data: { mode }
    });
  }
  async updateTitle(conversationId, title) {
    return prisma_default.conversation.update({
      where: { id: conversationId },
      data: { title }
    });
  }
  parseContent(content) {
    try {
      return JSON.parse(content);
    } catch {
      return content;
    }
  }
  formatMessagesForAI(messages) {
    const out = [];
    let pendingToolResults = [];
    const flushToolResults = () => {
      if (pendingToolResults.length === 0)
        return;
      const summary = pendingToolResults.map((c) => typeof c === "string" ? c : JSON.stringify(c)).join(`
`);
      out.push({
        role: "assistant",
        content: `[Tool results]
${summary}`
      });
      pendingToolResults = [];
    };
    for (const msg of messages) {
      const text2 = typeof msg.content === "string" ? msg.content : JSON.stringify(msg.content);
      if (msg.role === "tool") {
        pendingToolResults.push(text2);
        continue;
      }
      flushToolResults();
      if (msg.role === "user" || msg.role === "assistant" || msg.role === "system") {
        out.push({ role: msg.role, content: text2 });
      }
    }
    flushToolResults();
    return out;
  }
}

