// src/cli/workspace/scanner.ts
import fs16 from "node:fs/promises";
import fsSync from "node:fs";
import path20 from "node:path";
import { execSync } from "node:child_process";
var ALWAYS_IGNORE2 = new Set([
  "node_modules",
  ".next",
  "dist",
  "build",
  ".git",
  ".cache",
  "coverage",
  ".turbo",
  "out",
  ".expo",
  "android",
  "ios",
  ".venv",
  "venv",
  "__pycache__",
  "target",
  "bin",
  "obj",
  ".vercel",
  ".serverless",
  "*.pyc",
  ".env",
  ".env.local"
]);
var MAX_TREE_DEPTH = 2;
var MAX_DIR_CHILDREN = 40;
async function readGitignore(dir) {
  const ignore = new Set;
  try {
    const content = await fs16.readFile(path20.join(dir, ".gitignore"), "utf-8");
    for (const line2 of content.split(`
`)) {
      const trimmed = line2.trim();
      if (trimmed && !trimmed.startsWith("#")) {
        ignore.add(trimmed.replace(/\/$/, ""));
      }
    }
  } catch {}
  return ignore;
}
function shouldIgnore(name29, gitignore) {
  if (ALWAYS_IGNORE2.has(name29))
    return true;
  if (gitignore.has(name29))
    return true;
  if (name29.startsWith(".") && name29 !== ".gitignore")
    return true;
  return false;
}
async function scanDir(dirPath, gitignore, depth = 0) {
  if (depth > MAX_TREE_DEPTH)
    return [];
  const entries = [];
  let dirEntries = [];
  try {
    dirEntries = await fs16.readdir(dirPath);
  } catch {
    return [];
  }
  dirEntries.sort((a, b2) => {
    const aIsDir = !a.includes(".");
    const bIsDir = !b2.includes(".");
    if (aIsDir && !bIsDir)
      return -1;
    if (!aIsDir && bIsDir)
      return 1;
    return a.localeCompare(b2);
  });
  for (const name29 of dirEntries) {
    if (shouldIgnore(name29, gitignore))
      continue;
    if (entries.length >= MAX_DIR_CHILDREN)
      break;
    const fullPath = path20.join(dirPath, name29);
    let stat2;
    try {
      stat2 = await fs16.stat(fullPath);
    } catch {
      continue;
    }
    if (stat2.isDirectory()) {
      const children = await scanDir(fullPath, gitignore, depth + 1);
      entries.push({ name: name29, type: "dir", children });
    } else {
      entries.push({ name: name29, type: "file" });
    }
  }
  return entries;
}
async function countFiles(dirPath, gitignore) {
  let count = 0;
  let dirEntries = [];
  try {
    dirEntries = await fs16.readdir(dirPath);
  } catch {
    return 0;
  }
  for (const name29 of dirEntries) {
    if (shouldIgnore(name29, gitignore))
      continue;
    const fullPath = path20.join(dirPath, name29);
    try {
      const stat2 = await fs16.stat(fullPath);
      if (stat2.isDirectory()) {
        count += await countFiles(fullPath, gitignore);
      } else {
        count++;
      }
    } catch {}
  }
  return count;
}
function detectTechStack(dirPath) {
  const stack = [];
  try {
    const raw2 = fsSync.readFileSync(path20.join(dirPath, "package.json"), "utf-8");
    const pkg = JSON.parse(raw2);
    const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };
    if (allDeps.next)
      stack.push("Next.js");
    if (allDeps.react)
      stack.push("React");
    if (allDeps["@prisma/client"] || allDeps.prisma)
      stack.push("Prisma ORM");
    if (allDeps.tailwindcss)
      stack.push("Tailwind CSS");
    if (allDeps["better-auth"] || allDeps["@better-auth"])
      stack.push("Better-Auth");
    if (allDeps.express)
      stack.push("Express");
    if (allDeps["@trpc/client"] || allDeps["@trpc/server"])
      stack.push("tRPC");
    if (allDeps["@tanstack/react-query"] || allDeps["@tanstack/query"])
      stack.push("TanStack Query");
    if (allDeps.zustand)
      stack.push("Zustand");
    if (allDeps["socket.io"] || allDeps["socket.io-client"])
      stack.push("Socket.io");
    if (allDeps.drizzle || allDeps["drizzle-orm"])
      stack.push("Drizzle ORM");
    if (allDeps.vitest || allDeps.jest)
      stack.push(allDeps.vitest ? "Vitest" : "Jest");
    if (allDeps.eslint)
      stack.push("ESLint");
    if (allDeps.prettier)
      stack.push("Prettier");
    if (allDeps["next-auth"] || allDeps["@auth/core"])
      stack.push("Next-Auth");
    if (allDeps.shadcn || allDeps["@radix-ui"])
      stack.push("shadcn/ui");
    if (allDeps["@clerk/nextjs"] || allDeps.clerk)
      stack.push("Clerk");
    if (allDeps["aws-sdk"] || allDeps["@aws-sdk"])
      stack.push("AWS SDK");
    if (allDeps["graphql"] || allDeps["@apollo/client"])
      stack.push("GraphQL");
  } catch {}
  try {
    if (fsSync.existsSync(path20.join(dirPath, "turbo.json"))) {
      if (!stack.includes("Turborepo"))
        stack.push("Turborepo");
    }
  } catch {}
  return stack;
}
function getGitInfo(cwd) {
  try {
    const root = execSync("git rev-parse --show-toplevel", {
      cwd,
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "ignore"]
    }).trim();
    const branch = execSync("git rev-parse --abbrev-ref HEAD", {
      cwd,
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "ignore"]
    }).trim();
    return { isRepo: true, branch: branch || null, root };
  } catch {
    return { isRepo: false, branch: null, root: cwd };
  }
}
function readPackageJson(dirPath) {
  try {
    const raw2 = fsSync.readFileSync(path20.join(dirPath, "package.json"), "utf-8");
    return JSON.parse(raw2);
  } catch {
    return null;
  }
}
async function scanWorkspace(cwd) {
  const startDir = cwd || process.cwd();
  const { isRepo, branch, root } = getGitInfo(startDir);
  const workspaceRoot = root || startDir;
  const gitignore = await readGitignore(workspaceRoot);
  const gitignoreAtCwd = startDir !== workspaceRoot ? await readGitignore(startDir) : new Set;
  const combined = new Set;
  gitignore.forEach((x4) => combined.add(x4));
  gitignoreAtCwd.forEach((x4) => combined.add(x4));
  const [fileTree, fileCount, pkg] = await Promise.all([
    scanDir(workspaceRoot, combined, 0),
    countFiles(workspaceRoot, combined),
    Promise.resolve(readPackageJson(workspaceRoot))
  ]);
  const techStack = detectTechStack(workspaceRoot);
  const hasTsconfig = await fs16.access(path20.join(workspaceRoot, "tsconfig.json")).then(() => true).catch(() => false);
  const hasPrisma = await fs16.access(path20.join(workspaceRoot, "prisma", "schema.prisma")).then(() => true).catch(() => false);
  const isMonorepo = !!(pkg?.workspaces && pkg.workspaces.length > 0) || techStack.includes("Turborepo");
  return {
    dirName: path20.basename(workspaceRoot),
    fullPath: workspaceRoot,
    isGitRepo: isRepo,
    gitBranch: branch,
    fileCount,
    fileTree,
    projectName: pkg?.name || path20.basename(workspaceRoot),
    techStack,
    hasPackageJson: !!pkg,
    hasTsconfig,
    hasPrisma,
    isMonorepo,
    workspaceRoot
  };
}

