var NPM_PACKAGE = "supercode-cli";
async function checkForUpdate() {
  const thinking = createThinking("checking for update");
  try {
    const res = await fetch(`https://registry.npmjs.org/${NPM_PACKAGE}/latest`, {
      signal: AbortSignal.timeout(5000)
    });
    if (!res.ok) {
      thinking.fail("could not reach registry");
      return;
    }
    const data = await res.json();
    const latest = data.version;
    if (latest === version3) {
      thinking.succeed(`v${version3} (latest)`);
      return;
    }
    thinking.stop();
    console.log();
    console.log(`  ${source_default2.hex(theme.amber)("◆")}  ${source_default2.hex(theme.green).bold("Update available:")} ${source_default2.hex(theme.greenDim)(`v${version3}`)} → ${source_default2.hex(theme.greenGlow)(`v${latest}`)}`);
    console.log();
    const shouldUpdate = await le({
      message: "Update to latest version?",
      initialValue: true
    });
    if (R(shouldUpdate) || !shouldUpdate) {
      console.log(`  ${source_default2.hex(theme.greenMute)("Skipping update")}`);
      console.log();
      return;
    }
    const spinner = createThinking("updating supercode");
    try {
      const result = await Bun.$`npm install -g ${NPM_PACKAGE}@latest`.quiet();
      if (result.exitCode === 0) {
        spinner.succeed(`Updated to v${latest}`);
        console.log();
      } else {
        throw new Error(`exit code ${result.exitCode}`);
      }
    } catch {
      spinner.fail("Update failed");
      console.log(`  ${source_default2.hex(theme.greenMute)("Continuing with current version")}`);
      console.log();
    }
  } catch {
    thinking.fail("update check failed");
  }
}

